using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Documents;
using System.Text;
using System.Text.RegularExpressions;
using DomainConsole.Shared;
namespace DomainConsole;
public sealed class LogViewer:UserControl {
 public static readonly DependencyProperty TextProperty=DependencyProperty.Register(nameof(Text),typeof(string),typeof(LogViewer),new PropertyMetadata("",(d,e)=>((LogViewer)d).ScheduleRender()));
 public string Text {get=>(string)GetValue(TextProperty);set=>SetValue(TextProperty,value);}
 readonly StackPanel groups=new();readonly ScrollViewer scroll=new(){VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};
 readonly TextBox search=new(){MinWidth=70,ToolTip="Подсветить совпадения в кратком журнале. Полные исходные логи доступны кнопкой «Журналы»."};readonly ComboBox filter=new(){Width=115};readonly TextBlock counter=new(){VerticalAlignment=VerticalAlignment.Center,Foreground=Brushes.SlateGray,Margin=new(4,0,4,0)};
 readonly Dictionary<string,bool> expanded=new();readonly List<(Run Run,RichTextBox Box,Expander Group)> hits=new();int currentHit=-1;string? clearedText;bool renderPending;
 public bool AutoScroll {get;set;}
 public event EventHandler? CopyRequested;public event EventHandler? DownloadRequested;public event EventHandler? RefreshRequested;
 public LogViewer(){var dock=new DockPanel();var tools=new Grid{Margin=new(0,0,0,6)};tools.ColumnDefinitions.Add(new(){Width=new GridLength(1,GridUnitType.Star)});tools.ColumnDefinitions.Add(new(){Width=GridLength.Auto});tools.ColumnDefinitions.Add(new(){Width=GridLength.Auto});search.Margin=new(0,0,6,0);var field=new DockPanel();var navigation=new StackPanel{Orientation=Orientation.Horizontal};navigation.Children.Add(counter);foreach(var pair in new[]{("↑",-1),("↓",1)}){var button=new Button{Content=pair.Item1,ToolTip=pair.Item2<0?"Предыдущее совпадение":"Следующее совпадение"};int delta=pair.Item2;button.Click+=(s,e)=>MoveMatch(delta);navigation.Children.Add(button);}DockPanel.SetDock(navigation,Dock.Right);field.Children.Add(navigation);var searchField=new Grid();searchField.Children.Add(search);var hint=new TextBlock{Text="Поиск в журнале",Margin=new(6,6,0,0),Foreground=Brushes.SlateGray,IsHitTestVisible=false};searchField.Children.Add(hint);search.TextChanged+=(s,e)=>{hint.Visibility=search.Text.Length==0?Visibility.Visible:Visibility.Collapsed;ScheduleRender();};search.KeyDown+=(s,e)=>{if(e.Key==System.Windows.Input.Key.Enter){MoveMatch(System.Windows.Input.Keyboard.Modifiers.HasFlag(System.Windows.Input.ModifierKeys.Shift)?-1:1);e.Handled=true;}};field.Children.Add(searchField);tools.Children.Add(field);filter.ItemsSource=new[]{"Все записи","Ошибки","Замечания"};filter.SelectedIndex=0;filter.ToolTip="Фильтр краткого журнала";Grid.SetColumn(filter,1);tools.Children.Add(filter);var actions=new StackPanel{Orientation=Orientation.Horizontal};var copy=new Button{Content="Копировать",ToolTip="Копировать раскрытые разделы журнала с учётом фильтра."};copy.Click+=(s,e)=>CopyRequested?.Invoke(this,EventArgs.Empty);var download=new Button{Content="Журналы",ToolTip="Скачать полные исходные журналы выбранного задания."};download.Click+=(s,e)=>DownloadRequested?.Invoke(this,EventArgs.Empty);var clear=new Button{Content="Очистить",ToolTip="Очистить только окно вывода. История и файлы сохраняются; новый результат появится автоматически."};clear.Click+=(s,e)=>ClearDisplay();var refresh=new Button{Content="↻",ToolTip="Получить результат текущего задания и вернуть очищенный вывод."};refresh.Click+=(s,e)=>{clearedText=null;ScheduleRender();RefreshRequested?.Invoke(this,EventArgs.Empty);};foreach(var button in new[]{copy,download,clear,refresh}){button.Padding=new(5,4,5,4);button.Margin=new(2,0,0,0);button.MinWidth=0;button.FontSize=11;}actions.Children.Add(copy);actions.Children.Add(download);actions.Children.Add(clear);actions.Children.Add(refresh);Grid.SetColumn(actions,2);tools.Children.Add(actions);DockPanel.SetDock(tools,Dock.Top);dock.Children.Add(tools);groups.Background=new SolidColorBrush(Color.FromRgb(16,34,57));scroll.Background=groups.Background;scroll.Resources["ScrollTrack"]=new SolidColorBrush(Color.FromRgb(35,58,82));scroll.Resources["ScrollThumb"]=new SolidColorBrush(Color.FromRgb(109,135,155));scroll.Content=groups;dock.Children.Add(scroll);Content=dock;filter.SelectionChanged+=(s,e)=>ScheduleRender();}
 public static List<(string Title,string Body)> Sections(string text){var result=new List<(string,string)>();string title="Результат";var body=new StringBuilder();foreach(var line in text.Replace("\r\n","\n").Split('\n')){if(line.StartsWith("## ")){if(body.ToString().Trim().Length>0)result.Add((title,body.ToString().TrimEnd()));title=line[3..];body.Clear();}else body.AppendLine(line);}if(body.ToString().Trim().Length>0)result.Add((title,body.ToString().TrimEnd()));return result;}
 public string VisibleText()=>string.Join(Environment.NewLine+Environment.NewLine,groups.Children.OfType<Expander>().Where(e=>e.IsExpanded).Select(e=>((e.Header as TextBlock)?.Text??e.Header.ToString())+Environment.NewLine+(e.Tag as string??"")));
 public void ClearDisplay(){clearedText=Text;groups.Children.Clear();hits.Clear();currentHit=-1;counter.Text="";}
 public void SetExpanded(string title,bool open){expanded[title]=open;Render();}
 public static string LineTone(string line){if(Regex.IsMatch(line,@"(?i)ошибок:\s*0\b|без замечаний|не обнаружила нарушений|отчётность работает"))return "Success";if(Regex.IsMatch(line,@"(?i)предупреж|неполн|частичн|не расшифр|не подтвержд|ограничени|рекомендаци|WARNING|retry"))return "Warning";if(LogPresentation.Anomaly(line))return "Error";if(Regex.IsMatch(line,@"(?i)успешно|получен сервером|Succeeded|Очистка очереди.*не требуется"))return "Success";return "Normal";}
 void ScheduleRender(){if(renderPending)return;renderPending=true;Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Background,new Action(()=>{renderPending=false;Render();}));}
 public static List<(int Start,int Length)> MatchRanges(string text,string query){var result=new List<(int,int)>();if(string.IsNullOrEmpty(query))return result;int start=0,index;while(start<text.Length&&(index=text.IndexOf(query,start,StringComparison.OrdinalIgnoreCase))>=0){result.Add((index,query.Length));start=index+query.Length;}return result;}
 void MoveMatch(int delta){if(hits.Count==0)return;if(currentHit>=0)hits[currentHit].Run.Background=Brushes.DarkSlateBlue;currentHit=currentHit<0?(delta<0?hits.Count-1:0):(currentHit+delta+hits.Count)%hits.Count;var hit=hits[currentHit];hit.Run.Background=Brushes.DarkGoldenrod;hit.Group.IsExpanded=true;hit.Box.UpdateLayout();hit.Box.Selection.Select(hit.Run.ContentStart,hit.Run.ContentEnd);hit.Box.BringIntoView(hit.Run.ContentStart.GetCharacterRect(LogicalDirection.Forward));counter.Text=(currentHit+1)+" / "+hits.Count;}
 void Render(){if(clearedText==Text)return;clearedText=null;double offset=scroll.VerticalOffset;groups.Children.Clear();hits.Clear();currentHit=-1;int remainingLines=1800;foreach(var (title,body) in Sections(Text??"")){string display=body;if(filter.SelectedIndex==1)display=LogPresentation.ErrorContext(body);if(filter.SelectedIndex==2)display=string.Join("\n",body.Split('\n').Where(x=>LineTone(x)=="Warning"));if(filter.SelectedIndex>0&&(display.Length==0||display.StartsWith("В выбранном интервале")))continue;var lines=display.Split('\n');if(lines.Length>remainingLines)display=string.Join("\n",lines.Take(Math.Max(0,remainingLines)))+"\n… Краткий вывод ограничен. Полные исходные файлы — кнопка «Журналы».";remainingLines-=Math.Min(lines.Length,remainingLines);if(remainingLines==0&&groups.Children.Count>0&&display.StartsWith("\n…"))continue;var expander=new Expander{Header=new TextBlock{Text=title,Foreground=Brushes.White,FontWeight=FontWeights.SemiBold,Padding=new(6,5,6,5)},Background=new SolidColorBrush(Color.FromRgb(35,58,82)),Foreground=Brushes.White,Margin=new(0,0,0,1),IsExpanded=expanded.TryGetValue(title,out bool open)?open:!title.StartsWith("Технический")&&!title.StartsWith("Сбор диагностики")};var document=new FlowDocument{PagePadding=new(0)};var paragraph=new Paragraph{Margin=new(0)};var box=new RichTextBox{Document=document,IsReadOnly=true,IsDocumentEnabled=false,FontFamily=new FontFamily("Consolas"),Background=new SolidColorBrush(Color.FromRgb(16,34,57)),BorderThickness=new(0),Padding=new(8),VerticalScrollBarVisibility=ScrollBarVisibility.Disabled,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};foreach(var line in display.Split('\n')){string tone=LineTone(line);Brush color=tone=="Error"?Brushes.Salmon:tone=="Warning"?Brushes.Gold:tone=="Success"?Brushes.LightGreen:new SolidColorBrush(Color.FromRgb(215,230,250));var weight=tone is "Error" or "Warning"?FontWeights.SemiBold:FontWeights.Normal;int pos=0;foreach(var match in MatchRanges(line,search.Text)){if(match.Start>pos)paragraph.Inlines.Add(new Run(line[pos..match.Start]){Foreground=color,FontWeight=weight});var run=new Run(line.Substring(match.Start,match.Length)){Foreground=Brushes.White,Background=Brushes.DarkSlateBlue,FontWeight=FontWeights.Bold};paragraph.Inlines.Add(run);hits.Add((run,box,expander));pos=match.Start+match.Length;}if(pos<line.Length)paragraph.Inlines.Add(new Run(line[pos..]){Foreground=color,FontWeight=weight});paragraph.Inlines.Add(new LineBreak());}document.Blocks.Add(paragraph);expander.Tag=display;expander.Content=box;expander.Expanded+=(s,e)=>expanded[title]=true;expander.Collapsed+=(s,e)=>expanded[title]=false;groups.Children.Add(expander);}counter.Text=search.Text.Length==0?"":"0 / "+hits.Count;scroll.ScrollToVerticalOffset(offset);if(AutoScroll&&search.Text.Length==0)scroll.ScrollToEnd();}
}
